CREATE TABLE IF NOT EXISTS gis_phase367_spatial_queries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), query_type TEXT NOT NULL, certification_version TEXT NOT NULL, feature_id TEXT, state_code TEXT, result_count BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_phase367_queries_created ON gis_phase367_spatial_queries(created_at);